<?php
require_once __DIR__.'/alfa_acquiring.php';$user=av_current_user();$orderId=trim((string)($_GET['order']??''));$guestToken=trim((string)($_GET['token']??''));$orders=av_read_orders();$index=null;foreach($orders as $k=>$candidate){if(($candidate['id']??'')!==$orderId)continue;$owned=$user&&($candidate['user_id']??'')===($user['id']??'');$guest=empty($candidate['user_id'])&&av_guest_order_access($candidate,$guestToken);if($owned||$guest){$index=$k;break;}}$status='unknown';$message='Не удалось найти заказ.';
if($index!==null){$result=av_alfa_sync_order($orders[$index]);if(!empty($result['ok'])){av_write_orders($orders);av_alfa_payment_log($orders[$index]);$status=$result['status'];$message=$status==='paid'?'Оплата подтверждена. Спасибо!':($status==='declined'?'Платёж отклонён. Попробуйте ещё раз.':'Платёж обрабатывается. Статус обновится автоматически.');}else$message=$result['error']??'Не удалось проверить платёж.';}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Оплата — AV Rescue</title><style>body{margin:0;background:#08090a;color:#fff;font-family:Arial}.card{width:min(560px,calc(100% - 28px));margin:15vh auto;background:#111317;border:1px solid #30343a;border-radius:14px;padding:28px}b{color:#ed111c}.btn{display:inline-block;margin-top:18px;padding:13px 18px;border-radius:8px;background:#ed111c;color:#fff;text-decoration:none;font-weight:800}.muted{color:#aaa}</style></head><body><div class="card"><h1>AV<b>R</b> Rescue</h1><h2><?php echo htmlspecialchars($message);?></h2><p class="muted">Заказ <?php echo htmlspecialchars($orderId);?> · статус <?php echo htmlspecialchars(av_payment_status_label($status));?></p><a class="btn" href="<?php echo $user?'/account.php':'/guest-payment.php?order='.rawurlencode($orderId).'&token='.rawurlencode($guestToken);?>"><?php echo $user?'Вернуться в личный кабинет':'Вернуться к заказу';?></a></div></body></html>
